<?php
declare(strict_types=1);
// Existing handover validation retained for both API entry points.
function create_delivery_entry(array $p,array $current,bool $insideTransaction=false): array {
  $mode=text($p,'delivery_mode',16)?:'standard';if(!in_array($mode,['standard','walkin'],true))fail('Choose a valid delivery type.');if($mode==='walkin'&&$current['role']!=='super_admin'&&!can_submit_delivery_cash($current))fail('Walk-in delivery requires cash receiving access.',403);
  $walkinCash=$p['walkin_cash']??null;if(array_key_exists('walkin_cash',$p)&&($mode!=='walkin'||!is_array($walkinCash)))fail('Cash collection in this form is only available for walk-in deliveries.');
  $walkinKey=$walkinCash!==null?text($walkinCash,'request_key',100,true):null;if($walkinKey!==null&&!preg_match('/^[a-zA-Z0-9-]{16,100}$/D',$walkinKey))fail('Invalid cash receipt request key.');$walkinHash=$walkinCash!==null?shipment_version($p):null;
  $dated=day($p);$receiver=text($p,'receiver',100,true);$lines=$p['items']??[];if(!is_array($lines)||count($lines)<1||count($lines)>1000)fail('Select between 1 and 1000 pending bilties.');$ids=[];$clean=[];
  foreach($lines as $l){if(money($l,'bilty_received')||money($l,'service_received'))fail('Record cash in Delivery Cash Receiving after saving the handover.');$id=filter_var($l['id']??0,FILTER_VALIDATE_INT);if(!$id||isset($ids[$id]))fail('Select each bilty once.');$ids[$id]=true;$clean[]=['id'=>$id,'discount'=>money($l,'discount'),'bilty_received'=>money($l,'bilty_received'),'service_received'=>money($l,'service_received'),'loading'=>array_key_exists('loading',$l)?money($l,'loading'):null,'suzuki'=>array_key_exists('suzuki',$l)?money($l,'suzuki'):null];}
  $warnings=[];$save=function()use($p,$dated,$receiver,$clean,&$warnings,$current,$mode,$walkinCash,$walkinKey,$walkinHash){
   if($walkinKey!==null){$existing=one('SELECT * FROM walkin_delivery_requests WHERE request_key=?',[$walkinKey]);if($existing){if((int)$existing['submitted_by']!==(int)$current['id']||!hash_equals($existing['request_hash'],$walkinHash))throw new RuntimeException('This cash request key was already used for different values.',409);return [...json_decode($existing['result_json'],true,64,JSON_THROW_ON_ERROR),'replayed'=>true];}}
   $pendingId=(int)($p['pending_id']??0);$submission=null;
   if($pendingId){$submission=one("SELECT * FROM delivery_submissions WHERE id=? AND status='pending'",[$pendingId]);if(!$submission)throw new RuntimeException('This delivery submission is no longer pending.',409);if(!hash_equals(delivery_submission_version($submission),(string)($p['pending_version']??'')))throw new RuntimeException('This delivery submission changed. Reopen it before approving.',409);$originalIds=array_column(json_decode($submission['payload'],true,64,JSON_THROW_ON_ERROR)['items'],'id');$ids=array_column($clean,'id');sort($originalIds);sort($ids);if($originalIds!==$ids)throw new InvalidArgumentException('Keep the original bilties in this delivery submission.');}
   foreach($clean as $l){
    $reserved=one('SELECT submission_id FROM delivery_submission_items WHERE item_id=?',[$l['id']]);if($reserved&&(int)$reserved['submission_id']!==$pendingId)throw new RuntimeException('This bilty is already awaiting delivery approval.',409);
$item=one("SELECT i.*,s.kind,s.dated FROM items i JOIN shipments s ON s.id=i.shipment_id WHERE i.id=? AND i.status='pending' AND s.kind='incoming'",[$l['id']]);if(!$item||one('SELECT id FROM delivery_items WHERE item_id=?',[$l['id']]))throw new RuntimeException('A selected bilty is no longer pending. Refresh the list.',409);if($dated<$item['dated'])throw new InvalidArgumentException('Delivery date cannot be earlier than the arrival date.');$remaining=max(0,goods_total($item,'incoming')-(int)$item['advance']);if($l['discount']+$l['bilty_received']>$remaining)$warnings[]='Bilty '.$item['bilty'].': cash plus discount is greater than the remaining bilty amount.';if($l['service_received']>max(0,($l['loading']??(int)$item['loading'])+($l['suzuki']??(int)$item['suzuki'])))$warnings[]='Bilty '.$item['bilty'].': service cash is greater than loading plus Suzuki charges.';}
   run('INSERT INTO deliveries(reference,dated,receiver,mobile,cnic,remarks,cash_workflow,delivery_mode) VALUES(?,?,?,?,?,?,1,?)',['pending-'.bin2hex(random_bytes(8)),$dated,$receiver,text($p,'mobile',30),text($p,'cnic',30),text($p,'remarks',500),$mode]);$id=(int)db()->lastInsertId();$ref='DL-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);run('UPDATE deliveries SET reference=? WHERE id=?',[$ref,$id]);foreach($clean as $l){if($l['loading']!==null||$l['suzuki']!==null){run('UPDATE items SET loading=COALESCE(?,loading),suzuki=COALESCE(?,suzuki) WHERE id=?',[$l['loading'],$l['suzuki'],$l['id']]);audit('delivery_charges','item',$l['id']);}run('INSERT INTO delivery_items(delivery_id,item_id,discount,bilty_received,service_received,loading_charge,suzuki_charge) VALUES(?,?,?,?,?,(SELECT loading FROM items WHERE id=?),(SELECT suzuki FROM items WHERE id=?))',[$id,$l['id'],$l['discount'],$l['bilty_received'],$l['service_received'],$l['id'],$l['id']]);run("UPDATE items SET status='delivered' WHERE id=?",[$l['id']]);}sync_delivery_cash_invoice($id);run('UPDATE delivery_cash_invoices SET accounting_model=2 WHERE delivery_id=?',[$id]);audit('created','delivery',$id);if($submission){run("UPDATE delivery_submissions SET status='approved',approved_by=?,approved_at=CURRENT_TIMESTAMP,delivery_id=?,approved_payload=? WHERE id=?",[$current['id'],$id,json_encode($p,JSON_THROW_ON_ERROR),$pendingId]);run('DELETE FROM delivery_submission_items WHERE submission_id=?',[$pendingId]);audit('approved','delivery_submission',$pendingId);}$saved=['id'=>$id,'reference'=>$ref,'delivery_mode'=>$mode];if($walkinCash!==null){$cashResult=collect_walkin_delivery_cash($id,$walkinCash,$current,$dated);$saved['cash_recorded']=empty($cashResult['pending']);$saved['pending_cash']=!empty($cashResult['pending']);$saved['cash_id']=$cashResult['id'];run('INSERT INTO walkin_delivery_requests(request_key,submitted_by,request_hash,delivery_id,result_json) VALUES(?,?,?,?,?)',[$walkinKey,$current['id'],$walkinHash,$id,json_encode($saved,JSON_THROW_ON_ERROR)]);}return $saved;};$result=$insideTransaction?$save():transaction($save);$result['warnings']=$warnings;return $result;

}
